mapper.select:
SELECT e.exercise_id AS exerciseId,e.title,e.category_id AS categoryId,c.name AS categoryName,c.color, (SELECT i.text_value FROM exercise_items i WHERE i.exercise_id=e.exercise_id AND i.text_value LIKE CONCAT('%',#{keyword},'%') ORDER BY i.sort_order LIMIT 1) AS matched FROM exercises e JOIN practice_categories c ON c.category_id=e.category_id WHERE e.active=TRUE AND c.active=TRUE AND (e.title LIKE CONCAT('%',#{keyword},'%') OR EXISTS (SELECT 1 FROM exercise_items i WHERE i.exercise_id=e.exercise_id AND i.text_value LIKE CONCAT('%',#{keyword},'%')))
AND e.exercise_id NOT IN #{id}
ORDER BY EXISTS (SELECT 1 FROM practice_attempts pa WHERE pa.student_id=#{studentId} AND pa.exercise_id=e.exercise_id),c.sort_order,e.sort_order,e.exercise_id LIMIT #{limit}
